package com.idfc.ai.runbook.diff; import com.fasterxml.jackson.databind.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class RunbookComparator { private final SectionFingerprintService fp; public RunbookComparator(SectionFingerprintService f){fp=f;} public OperationalDiff compare(JsonNode current,JsonNode previous){Map<String,String> now=fp.fingerprints(current);if(previous==null)return new OperationalDiff(true,List.of("firstRun"),now);Map<String,String> old=fp.fingerprints(previous);List<String> changed=now.keySet().stream().filter(k->!Objects.equals(now.get(k),old.get(k))).toList();return new OperationalDiff(!changed.isEmpty(),changed,now);} }
